async function fetchWithTimeout(url, options = {}, timeoutMs = 12000) {
    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : null;
    try {
        return await fetch(url, { ...options, signal: controller?.signal });
    }
    finally {
        if (timer)
            clearTimeout(timer);
    }
}
async function queryUSDAFDC(query, { allowDemo = false } = {}) {
    const usdaKey = getUsdaKey({ allowDemo });
    if (!usdaKey)
        return [];
    try {
        const res = await fetchWithTimeout(`https://api.nal.usda.gov/fdc/v1/foods/search?api_key=${encodeURIComponent(usdaKey)}&query=${encodeURIComponent(query)}&pageSize=10`);
        const data = await res.json();
        if (!data.foods)
            return [];
        return data.foods.map(f => f.dataType === 'Branded'
            ? foodFromUsdaBranded(f, f.gtinUpc || '')
            : { ...normalizeUSDANutrients(f), name: titleCaseIfShouting(f.description) });
    }
    catch (err) {
        console.error("USDA Search error:", err);
        return [];
    }
}
// Open Food Facts' search server is often overloaded (HTTP 503), so a failed
// search is retried once before giving up.
async function searchOpenFoodFacts(query, { retries = 1 } = {}) {
    try {
        const url = `https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(query)}&search_simple=1&action=process&json=1&page_size=15&fields=code,product_name,product_name_en,generic_name,brands,nutriments,serving_quantity,serving_quantity_unit,serving_size,image_front_small_url`;
        const res = await fetchWithTimeout(url);
        if (!res.ok)
            throw new Error(`Open Food Facts search returned ${res.status}`);
        const data = await res.json();
        if (!data.products)
            return [];
        return data.products
            .map(p => foodFromOpenFoodFactsProduct(p))
            .filter(f => f.hasName && !f.missingNutrition)
            .map(f => ({ ...f, name: f.brand ? `${f.name} (${f.brand})` : f.name }));
    }
    catch (err) {
        if (retries > 0) {
            await new Promise(resolve => setTimeout(resolve, 800));
            return searchOpenFoodFacts(query, { retries: retries - 1 });
        }
        console.warn("Open Food Facts search unavailable:", err);
        throw new Error('Open Food Facts search is not responding right now.');
    }
}
// GEMINI AI (optional; key lives only on this device)
function getGeminiKey() {
    try {
        return localStorage.getItem(GEMINI_KEY_STORAGE) || CONFIG.geminiApiKey || '';
    }
    catch (e) {
        return CONFIG.geminiApiKey || '';
    }
}
function parseModelJson(text) {
    if (!text)
        throw new Error('The AI returned an empty response.');
    const cleaned = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
    return JSON.parse(cleaned);
}
async function callGemini(parts, { timeoutMs = 45000, schema = null } = {}) {
    const key = getGeminiKey();
    if (!key)
        throw new Error('Add your Gemini API key in Settings to use AI features.');
    const generationConfig = { responseMimeType: 'application/json', temperature: 0.2 };
    if (schema)
        generationConfig.responseSchema = schema;
    let res, data;
    for (;;) {
        const model = GEMINI_MODELS[geminiModelIndex];
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`;
        try {
            res = await fetchWithTimeout(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key },
                body: JSON.stringify({ contents: [{ parts }], generationConfig })
            }, timeoutMs);
        }
        catch (err) {
            throw new Error(err?.name === 'AbortError' ? 'The AI request timed out. Try again.' : 'Could not reach Gemini. Check your connection.');
        }
        data = {};
        try {
            data = await res.json();
        }
        catch (e) { /* non-JSON error page */ }
        // Model retired or not available to this key: try the next one.
        const unavailable = res.status === 404 || (res.status === 400 && /model.*(not found|not supported|unsupported)|no longer available/i.test(data?.error?.message || ''));
        if (unavailable && geminiModelIndex < GEMINI_MODELS.length - 1) {
            geminiModelIndex++;
            continue;
        }
        break;
    }
    if (!res.ok) {
        const msg = data?.error?.message || `Gemini error (${res.status}).`;
        if (res.status === 400 && /api key/i.test(msg))
            throw new Error('Gemini rejected the API key. Check it in Settings.');
        if (res.status === 403)
            throw new Error('This API key is not allowed to use Gemini. Check it in Settings.');
        if (res.status === 429)
            throw new Error('Gemini rate limit reached. Wait a minute and try again.');
        throw new Error(msg);
    }
    const text = data?.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('');
    return parseModelJson(text);
}
