async function queryGeminiBarcodeDigits(image) {
    const prompt = `This photo shows a retail product barcode (EAN-13, EAN-8, UPC-A or UPC-E). Read the human-readable digits printed under or beside the bars, left to right, including the small digits at the far left and right edges. Return only digits in "digits" (no spaces). If any digit is unreadable, set readable to false and give your best reading.`;
    const schema = { type: 'OBJECT', properties: { digits: { type: 'STRING' }, readable: { type: 'BOOLEAN' } }, required: ['digits', 'readable'] };
    const result = await callGemini([{ text: prompt }, { inline_data: { mime_type: image.mimeType, data: image.base64 } }], { timeoutMs: 30000, schema });
    const r = Array.isArray(result) ? result[0] : result;
    return { digits: String(r?.digits || '').replace(/\D/g, ''), readable: r?.readable !== false };
}
// STATE PERSISTENCE LOGIC
const LOCAL_STORAGE_KEY = 'macroflow_v2_state';
const MEAL_KEYS = ['breakfast', 'lunch', 'dinner', 'snacks'];
const MEAL_LABELS = { breakfast: 'Breakfast', lunch: 'Lunch', dinner: 'Dinner', snacks: 'Snacks' };
function saveStateToLocalStorage() {
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(appState));
    }
    catch (e) {
        console.error('Could not save MacroFlow data:', e);
        showToast('Could not save — browser storage may be full or blocked.', true);
    }
}
// Older versions reused food IDs. Repair duplicates without altering nutrition.
function ensureUniqueDiaryEntryIds() {
    const seen = new Set();
    for (const log of Object.values(appState.dailyLogs || {})) {
        for (const entries of Object.values(log?.meals || {})) {
            if (!Array.isArray(entries))
                continue;
            for (const entry of entries) {
                if (!entry.id || seen.has(entry.id))
                    entry.id = createDiaryEntryId();
                seen.add(entry.id);
            }
        }
    }
}
function loadStateFromLocalStorage() {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (data) {
        try {
            const parsed = JSON.parse(data);
            appState = { ...appState, ...parsed };
            ensureUniqueDiaryEntryIds();
        }
        catch (e) {
            console.warn("Corrupt local storage database. Reverting...", e);
        }
    }
}
function getDayLog(dateKey = appState.currentDate) {
    return appState.dailyLogs[dateKey] || { meals: { breakfast: [], lunch: [], dinner: [], snacks: [] }, water: 0 };
}
function ensureDayLog(dateKey = appState.currentDate) {
    if (!appState.dailyLogs[dateKey]) {
        appState.dailyLogs[dateKey] = { meals: { breakfast: [], lunch: [], dinner: [], snacks: [] }, water: 0 };
    }
    const log = appState.dailyLogs[dateKey];
    if (!log.meals)
        log.meals = {};
    MEAL_KEYS.forEach(m => { if (!Array.isArray(log.meals[m]))
        log.meals[m] = []; });
    return log;
}
function dayTotals(dateKey = appState.currentDate) {
    const totals = { calories: 0, protein: 0, carbs: 0, fats: 0 };
    Object.values(getDayLog(dateKey).meals || {}).forEach(foods => (foods || []).forEach(f => {
        totals.calories += f.calories || 0;
        totals.protein += f.protein || 0;
        totals.carbs += f.carbs || 0;
        totals.fats += f.fats || 0;
    }));
    return totals;
}
function guessMealForNow() {
    const h = new Date().getHours();
    if (h < 11)
        return 'breakfast';
    if (h < 15)
        return 'lunch';
    if (h >= 17 && h < 22)
        return 'dinner';
    return 'snacks';
}
// DATE NAVIGATION LOGIC
function navigateDate(offset) {
    const d = new Date(appState.currentDate + 'T12:00:00');
    d.setDate(d.getDate() + offset);
    appState.currentDate = localDateKey(d);
    renderDateNavigator();
    renderAll();
    renderFastingUI();
    if (appState.activeTab === 'dashboard')
        renderDashboardTab();
    saveStateToLocalStorage();
}
function jumpToToday() {
    if (appState.currentDate === localDateKey())
        return;
    selectDate(localDateKey());
}
function selectDate(dateKey) {
    if (dateKey === appState.currentDate)
        return;
    appState.currentDate = dateKey;
    renderAll();
    renderFastingUI();
    if (appState.activeTab === 'dashboard')
        renderDashboardTab();
    saveStateToLocalStorage();
}
function shiftWeek(direction) {
    const d = new Date(appState.currentDate + 'T12:00:00');
    d.setDate(d.getDate() + direction * 7);
    selectDate(localDateKey(d));
}
function relativeDayLabel(dateStr) {
    if (dateStr === localDateKey())
        return 'Today';
    if (dateStr === localDateKey(localDayOffset(-1)))
        return 'Yesterday';
    if (dateStr === localDateKey(localDayOffset(1)))
        return 'Tomorrow';
    return new Date(dateStr + 'T12:00:00').toLocaleDateString('en-US', { weekday: 'long' });
}
function renderDateNavigator() {
    const dateStr = appState.currentDate;
    const d = new Date(dateStr + 'T12:00:00');
    const fullDate = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
    const tab = appState.activeTab || 'nutrition';
    if (tab === 'nutrition') {
        const rel = relativeDayLabel(dateStr);
        document.getElementById('header-title').innerText = rel;
        document.getElementById('header-eyebrow').innerText = /day$/.test(rel) && !['Today', 'Yesterday'].includes(rel)
            ? d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: d.getFullYear() !== new Date().getFullYear() ? 'numeric' : undefined })
            : fullDate;
    }
    else {
        document.getElementById('header-title').innerText = TAB_TITLES[tab];
        document.getElementById('header-eyebrow').innerText = tab === 'progress' ? `Last ${appState.progressRange || 30} days` : `${relativeDayLabel(dateStr)} · ${d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`;
    }
    renderWeekStrip();
}
function renderWeekStrip() {
    const container = document.getElementById('week-days');
    if (!container)
        return;
    container.innerHTML = '';
    // Show the 7 days ending today; step back or forward a week at a time
    // so the strip never jumps while you tap between visible days.
    const todayKey = localDateKey();
    const selectedKey = appState.currentDate;
    const end = new Date(todayKey + 'T12:00:00');
    while (localDateKey(end) < selectedKey)
        end.setDate(end.getDate() + 7);
    const start = new Date(end);
    start.setDate(end.getDate() - 6);
    while (localDateKey(start) > selectedKey) {
        start.setDate(start.getDate() - 7);
        end.setDate(end.getDate() - 7);
    }
    const circumference = 2 * Math.PI * 15;
    for (let i = 0; i < 7; i++) {
        const day = new Date(start);
        day.setDate(start.getDate() + i);
        const key = localDateKey(day);
        const kcal = dayTotals(key).calories;
        const goal = dayGoal(key) || 1;
        const fraction = Math.min(1, kcal / goal);
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `day${key === appState.currentDate ? ' is-selected' : ''}${key === todayKey ? ' is-today' : ''}${key > todayKey ? ' is-future' : ''}`;
        if (btn.setAttribute)
            btn.setAttribute('aria-label', `${day.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}${kcal ? `, ${kcal} kcal` : ''}`);
        btn.innerHTML = `
            <span class="dow">${day.toLocaleDateString('en-US', { weekday: 'narrow' })}</span>
            <span class="dnum"><svg viewBox="0 0 34 34" aria-hidden="true">${key <= todayKey ? '<circle class="track" cx="17" cy="17" r="15"/>' : ''}${kcal ? `<circle class="prog${kcal > goal * 1.05 ? ' over' : ''}" cx="17" cy="17" r="15" stroke-dasharray="${circumference.toFixed(2)}" stroke-dashoffset="${(circumference * (1 - fraction)).toFixed(2)}"/>` : ''}</svg>${day.getDate()}</span>`;
        btn.onclick = () => selectDate(key);
        container.appendChild(btn);
    }
}
function formatDateShort(dateStr) {
    const d = new Date(dateStr + 'T12:00:00');
    const options = { weekday: 'short', month: 'short', day: 'numeric' };
    return d.toLocaleDateString('en-US', options);
}
// TAB MECHANISMS
const TAB_TITLES = { nutrition: 'Today', dashboard: 'Insights', progress: 'Progress' };
function switchTab(tabId) {
    if (!TAB_TITLES[tabId])
        tabId = 'nutrition';
    appState.activeTab = tabId;
    Object.keys(TAB_TITLES).forEach(id => {
        const el = document.getElementById(`tab-content-${id}`);
        const btn = document.getElementById(`mb-${id}`);
        if (el)
            el.classList.toggle('hidden', id !== tabId);
        if (btn)
            btn.classList.toggle('is-active', id === tabId);
    });
    document.getElementById('date-bar').classList.toggle('hidden', tabId === 'progress');
    document.getElementById('topbar-actions').classList.toggle('hidden', tabId !== 'nutrition');
    renderDateNavigator();
    if (tabId === 'progress') {
        setProgressSubTab(appState.progressSubTab || 'weight');
    }
    else if (tabId === 'dashboard') {
        renderDashboardTab();
    }
    if (typeof window.scrollTo === 'function')
        window.scrollTo(0, 0);
    saveStateToLocalStorage();
}
function renderDashboardTab() {
    const totals = dayTotals();
    const isToday = appState.currentDate === localDateKey();
    document.getElementById('dash-day-label').innerText = isToday ? 'Eaten today' : `Eaten ${formatDateShort(appState.currentDate)}`;
    document.getElementById('dash-cal').innerText = Number(totals.calories).toLocaleString('en-US');
    document.getElementById('dash-protein').innerText = Math.round(totals.protein);
    document.getElementById('dash-remaining').innerText = Math.max(0, dayGoal() - totals.calories).toLocaleString('en-US');
    calculateStreak();
    renderWeeklyReport();
    renderInsightsCharts();
    renderFastingUI();
}
