function renderInsightsCharts() {
    const days = appState.insightsRange || 7;
    [7, 14, 30].forEach(d => document.getElementById(`insights-range-${d}`).classList.toggle('is-active', d === days));
    const series = dailySeries(days).map(d => ({ ...d, selected: d.key === appState.currentDate }));
    const logged = series.filter(d => d.kcal > 0);
    const fmt = n => Math.round(n).toLocaleString('en-US');
    const avg = (list, key) => list.length ? list.reduce((sum, d) => sum + (d[key] || 0), 0) / list.length : 0;
    const rangeText = `last ${days} days`;
    document.getElementById('ins-cal-range').innerText = rangeText;
    document.getElementById('ins-split-range').innerText = `average, ${rangeText}`;
    // Calories
    const calEl = document.getElementById('ins-cal-chart');
    const onTarget = logged.filter(d => Math.abs(d.kcal - d.goal) <= d.goal * 0.1).length;
    document.getElementById('ins-cal-kpis').innerHTML = kpisHtml([
        [logged.length ? `${fmt(avg(logged, 'kcal'))}<small>kcal</small>` : '—', 'avg per logged day', 'var(--kcal)'],
        [`${onTarget}<small>/ ${logged.length}</small>`, 'days within 10%'],
        [`${logged.length}<small>/ ${days}</small>`, 'days logged']
    ]);
    calEl.innerHTML = logged.length
        ? barChartSvg({ width: chartWidthOf(calEl), bars: series.map(d => ({ ...d, segments: macroSegments(d) })), goal: appState.targets.calories || 2000, onTap: 'selectInsightsDay' })
        : chartEmpty('fa-chart-column', 'Log food to see your daily calories here.');
    // Eaten vs burned (finished days with burn data)
    const today = localDateKey();
    const balance = series.filter(d => d.burned && d.kcal > 0 && d.key < today);
    const balEl = document.getElementById('ins-bal-chart');
    document.getElementById('ins-bal-legend').classList.toggle('hidden', !balance.length);
    if (balance.length) {
        const net = avg(balance, 'kcal') - avg(balance, 'burned');
        document.getElementById('ins-bal-kpis').innerHTML = kpisHtml([
            [`${fmt(avg(balance, 'kcal'))}<small>kcal</small>`, 'avg eaten', 'var(--kcal)'],
            [`${fmt(avg(balance, 'burned'))}<small>kcal</small>`, 'avg burned', 'var(--burn)'],
            [`${net > 0 ? '+' : '−'}${fmt(Math.abs(net))}`, net > 0 ? 'surplus / day' : 'deficit / day', net > 0 ? 'var(--fat-2)' : 'var(--carbs-2)']
        ]);
        balEl.innerHTML = pairBarChartSvg({ width: chartWidthOf(balEl), items: series.map(d => ({ ...d, a: d.key < today && d.burned ? d.kcal : 0, b: d.key < today ? d.burned || 0 : 0 })), colors: ['var(--kcal)', 'var(--burn)'], onTap: 'selectInsightsDay' });
    }
    else {
        document.getElementById('ins-bal-kpis').innerHTML = '';
        balEl.innerHTML = chartEmpty('fa-heart-pulse', 'See calories eaten next to calories burned once burn data arrives from Apple Health (Google Health, Fitbit) or an import.', '<button class="btn btn-soft btn-sm" onclick="syncFromAppleHealth()"><i class="fa-brands fa-apple"></i>Sync Apple Health</button>');
    }
    // Protein
    const proteinTarget = appState.targets.protein || 150;
    document.getElementById('ins-protein-target').innerText = `target ${proteinTarget} g`;
    const proteinEl = document.getElementById('ins-protein-chart');
    const hit = logged.filter(d => d.protein >= proteinTarget * 0.9).length;
    document.getElementById('ins-protein-kpis').innerHTML = kpisHtml([
        [logged.length ? `${fmt(avg(logged, 'protein'))}<small>g</small>` : '—', 'avg per logged day', 'var(--protein)'],
        [`${hit}<small>/ ${logged.length}</small>`, 'days at 90%+ of target']
    ]);
    proteinEl.innerHTML = logged.length
        ? barChartSvg({ width: chartWidthOf(proteinEl), height: 150, bars: series.map(d => ({ ...d, segments: [{ value: d.protein, color: d.protein >= proteinTarget * 0.9 ? 'var(--protein)' : 'rgba(255,55,95,0.45)' }] })), goal: proteinTarget, goalLabel: 'Target', fmt: n => `${Math.round(n)}`, onTap: 'selectInsightsDay' })
        : chartEmpty('fa-dumbbell', 'Log food to see protein by day.');
    // Macro split (average of logged days) vs targets
    const avgP = avg(logged, 'protein'), avgC = avg(logged, 'carbs'), avgF = avg(logged, 'fats');
    renderMacroPieChart(avgP, avgC, avgF);
    const t = appState.targets;
    const targetKcal = (t.protein || 0) * 4 + (t.carbs || 0) * 4 + (t.fats || 0) * 9;
    const pct = (p, c, f) => { const total = p * 4 + c * 4 + f * 9; return total ? [p * 4 / total, c * 4 / total, f * 9 / total].map(x => Math.round(x * 100)) : [0, 0, 0]; };
    const bar = vals => `<div class="split-bar">${vals.map((v, i) => v ? `<div style="width:${v}%;background:${['var(--protein)', 'var(--carbs)', 'var(--fat)'][i]}">${v >= 12 ? `${v}%` : ''}</div>` : '').join('')}</div>`;
    document.getElementById('ins-split-bars').innerHTML = logged.length && targetKcal
        ? `<div class="split-row"><span>You</span>${bar(pct(avgP, avgC, avgF))}</div><div class="split-row"><span>Target</span>${bar(pct(t.protein, t.carbs, t.fats))}</div>`
        : '';
    // Steps
    const withSteps = series.filter(d => d.steps !== null && d.steps !== undefined);
    document.getElementById('ins-steps-card').classList.toggle('hidden', !withSteps.length);
    if (withSteps.length) {
        document.getElementById('ins-steps-avg').innerText = `avg ${fmt(avg(withSteps, 'steps'))} / day`;
        const stepsEl = document.getElementById('ins-steps-chart');
        stepsEl.innerHTML = barChartSvg({ width: chartWidthOf(stepsEl), height: 140, bars: series.map(d => ({ ...d, segments: [{ value: d.steps || 0, color: 'var(--water)' }] })), goal: 10000, goalLabel: '', onTap: 'selectInsightsDay' });
    }
}
