// FOOD LOG MUTATIONS
function logFood(food, meal, { silent = false } = {}) {
    if (!MEAL_KEYS.includes(meal))
        meal = guessMealForNow();
    const dateKey = appState.currentDate;
    const log = ensureDayLog(dateKey);
    const normalized = normalizeNutritionObject(food);
    // Every log is independent, even when re-adding the same custom food.
    normalized.id = createDiaryEntryId();
    normalized.timestamp = new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
    log.meals[meal].push(normalized);
    updateFoodMemory(normalized, meal);
    const target = appState.targets.calories;
    const newTotal = dayTotals(dateKey).calories;
    const prevTotal = newTotal - normalized.calories;
    if (prevTotal < target && newTotal >= target && newTotal <= target * 1.15) {
        triggerConfetti();
    }
    if (!silent)
        showToast(`Added ${normalized.name} to ${MEAL_LABELS[meal].toLowerCase()} · ${normalized.calories} kcal`);
    renderAll();
    saveStateToLocalStorage();
    return normalized;
}
let lastRemovedEntry = null;
function removeFood(id, meal, dateKey = appState.currentDate) {
    const entries = appState.dailyLogs[dateKey]?.meals?.[meal];
    if (entries) {
        const index = entries.findIndex(x => x.id === id);
        if (index >= 0)
            lastRemovedEntry = { dateKey, meal, index, entry: entries[index] };
        appState.dailyLogs[dateKey].meals[meal] = entries.filter(x => x.id !== id);
    }
    showToast('Entry removed.', false, lastRemovedEntry ? { label: 'Undo', onClick: undoRemoveFood } : null);
    renderAll();
    saveStateToLocalStorage();
}
function undoRemoveFood() {
    if (!lastRemovedEntry)
        return;
    const { dateKey, meal, index, entry } = lastRemovedEntry;
    const log = ensureDayLog(dateKey);
    log.meals[meal].splice(Math.min(index, log.meals[meal].length), 0, entry);
    lastRemovedEntry = null;
    renderAll();
    saveStateToLocalStorage();
}
// SUGGESTIONS MEMORY PIPELINE
function updateFoodMemory(food, meal) {
    const hash = food.name.toLowerCase().trim();
    if (!appState.foodFrequency)
        appState.foodFrequency = {};
    if (!appState.foodFrequency[hash]) {
        appState.foodFrequency[hash] = { food: food, count: 0, meals: [] };
    }
    const entry = appState.foodFrequency[hash];
    entry.food = food;
    entry.count++;
    entry.lastUsed = appState.currentDate;
    entry.lastUsedAt = Date.now();
    if (!entry.meals.includes(meal))
        entry.meals.push(meal);
}
function getSuggestionsForMeal(meal) {
    if (!appState.foodFrequency)
        return [];
    return Object.values(appState.foodFrequency)
        .filter(x => x.meals.includes(meal))
        .sort((a, b) => b.count - a.count)
        .map(x => x.food)
        .slice(0, 5);
}
function getRecentFoods(limit = 12) {
    return Object.values(appState.foodFrequency || {})
        .sort((a, b) => (b.lastUsedAt || 0) - (a.lastUsedAt || 0) || String(b.lastUsed || '').localeCompare(String(a.lastUsed || '')) || b.count - a.count)
        .map(x => x.food)
        .slice(0, limit);
}
function renderSmartSuggestionSlot(meal) {
    const container = document.getElementById(`suggestion-slot-${meal}`);
    container.innerHTML = '';
    const count = (getDayLog().meals?.[meal] || []).length;
    document.getElementById(`meal-save-${meal}`).classList.toggle('hidden', count < 2);
    if (count >= 2)
        return;
    // Only suggest for an empty meal, so logged days stay uncluttered.
    if (count)
        return;
    const last = lastMealBefore(meal);
    if (last) {
        const kcal = last.foods.reduce((sum, f) => sum + (f.calories || 0), 0);
        const repeat = document.createElement('button');
        repeat.type = 'button';
        repeat.className = 'suggest';
        repeat.onclick = () => repeatMealFrom(last.key, meal);
        repeat.innerHTML = `<i class="fa-solid fa-clock-rotate-left"></i>
            <span class="min-w-0 truncate">${last.label === 'yesterday' ? 'Same as yesterday' : `Same as ${escapeHTML(last.label)}`}: <b>${escapeHTML(last.foods.map(f => f.name).join(', '))}</b></span>
            <span class="plus">+ ${kcal.toLocaleString('en-US')} kcal</span>`;
        container.appendChild(repeat);
        return;
    }
    const favorite = getSuggestionsForMeal(meal)[0];
    if (!favorite)
        return;
    const card = document.createElement('button');
    card.type = 'button';
    card.className = "suggest";
    card.onclick = () => logFood(favorite, meal);
    card.innerHTML = `
        <i class="fa-regular fa-star"></i>
        <span class="min-w-0 truncate">Your usual: <b>${escapeHTML(favorite.name)}</b></span>
        <span class="plus">+ ${favorite.calories} kcal</span>
    `;
    container.appendChild(card);
}
// MICROS DYNAMIC SYSTEM
function computeMicrosForDay() {
    const microLogged = {};
    micronutrients.forEach(m => microLogged[m.id] = 0);
    Object.values(getDayLog().meals || {}).forEach(meal => (meal || []).forEach(food => {
        if (food.micros)
            micronutrients.forEach(m => { microLogged[m.id] += (food.micros[m.id] || 0); });
    }));
    return microLogged;
}
function updateMicronutrientsVisuals(microLogged) {
    micronutrients.forEach(m => {
        const logged = microLogged[m.id] || 0;
        const target = appState.targets[m.targetKey] || 1;
        const percent = Math.min(100, (logged / target) * 100);
        const labelLogged = document.getElementById(`logged-${m.id}`);
        const bar = document.getElementById(`bar-${m.id}`);
        if (labelLogged)
            labelLogged.innerText = Math.round(logged * 10) / 10;
        if (bar) {
            bar.style.width = `${percent}%`;
            bar.style.background = (m.isLimit && logged > target) ? 'var(--danger)' : (logged >= target ? 'var(--brand)' : 'var(--carbs)');
        }
    });
}
function toggleMicrosPanel() {
    const panel = document.getElementById('micros-panel-content');
    const toggle = document.getElementById('micros-toggle');
    const opening = panel.classList.contains('hidden');
    panel.classList.toggle('hidden', !opening);
    if (toggle.setAttribute)
        toggle.setAttribute('aria-expanded', String(opening));
    if (opening)
        initializeMicronutrientsUI();
}
function initializeMicronutrientsUI() {
    const container = document.getElementById('micros-panel-content');
    container.innerHTML = '';
    const categories = [...new Set(micronutrients.map(m => m.category))];
    categories.forEach((cat, index) => {
        const catId = `micros-group-${index}`;
        const group = document.createElement('div');
        group.className = "micro-group";
        group.innerHTML = `
            <button type="button" onclick="toggleSubCategory('${catId}')"><span>${escapeHTML(cat)}</span><i id="chevron-${catId}" class="fa-solid fa-chevron-down" style="transition:transform .2s"></i></button>
            <div id="container-${catId}" class="hidden"></div>
        `;
        container.appendChild(group);
        const listContainer = group.querySelector(`#container-${catId}`);
        micronutrients.filter(m => m.category === cat).forEach(m => {
            const row = document.createElement('div');
            row.className = "micro-row";
            row.onclick = () => toggleMicroContribution(m.id);
            row.innerHTML = `
                <div class="top"><span>${escapeHTML(m.name)}${m.isLimit ? ' <span class="tiny faint">(limit)</span>' : ''}</span>
                    <span class="muted num"><b id="logged-${m.id}" style="color:var(--text)">0</b> / ${appState.targets[m.targetKey]} ${m.unit}</span></div>
                <div class="bar thin"><div id="bar-${m.id}" style="width:0%"></div></div>
                <div id="contrib-${m.id}" class="hidden small muted" style="margin-top:8px"></div>
            `;
            listContainer.appendChild(row);
        });
    });
    updateMicronutrientsVisuals(computeMicrosForDay());
}
function toggleMicroContribution(microId) {
    const container = document.getElementById(`contrib-${microId}`);
    if (!container)
        return;
    if (!container.classList.contains('hidden')) {
        container.classList.add('hidden');
        return;
    }
    container.classList.remove('hidden');
    container.innerHTML = '';
    const contributors = [];
    Object.values(getDayLog().meals || {}).forEach(meal => (meal || []).forEach(food => {
        const val = food.micros?.[microId] || 0;
        if (val > 0)
            contributors.push({ name: food.name, value: val });
    }));
    if (contributors.length === 0) {
        container.innerHTML = `<p>No logged food reports this nutrient.</p>`;
        return;
    }
    contributors.sort((a, b) => b.value - a.value);
    const m = micronutrients.find(item => item.id === microId);
    contributors.forEach(c => {
        const div = document.createElement('div');
        div.className = "flex justify-between gap-3 py-0.5";
        div.innerHTML = `<span class="truncate">${escapeHTML(c.name)}</span><b style="color:var(--brand)">+${c.value.toFixed(1)} ${m.unit}</b>`;
        container.appendChild(div);
    });
}
function toggleSubCategory(catId) {
    const el = document.getElementById(`container-${catId}`);
    const chevron = document.getElementById(`chevron-${catId}`);
    const opening = el.classList.contains('hidden');
    el.classList.toggle('hidden', !opening);
    chevron.style.transform = opening ? 'rotate(180deg)' : 'rotate(0deg)';
}
