        sub = 'weight';
    appState.progressSubTab = sub;
    ['weight', 'strength', 'calories'].forEach(key => {
        document.getElementById(`sub-tab-${key}-btn`).classList.toggle('is-active', key === sub);
        document.getElementById(`sub-panel-${key}`).classList.toggle('hidden', key !== sub);
    });
    calculateWeightStats();
    calculateStrengthStats();
    if (sub === 'weight')
        renderProgressTab();
    else if (sub === 'strength')
        renderStrengthSubTab();
    else
        renderCalorieTrends();
