function renderWeeklyAveragesTable() {
    const table = document.getElementById('weekly-averages-table-body');
    table.innerHTML = '';
    const data = getFilteredWeightHistory();
    if (data.length === 0) {
        table.innerHTML = `<tr><td colspan="3" class="text-center muted" style="padding:20px">No weigh-ins in this period.</td></tr>`;
        return;
    }
    const grouped = {};
    const order = [];
    data.forEach(item => {
        const date = new Date(item.date + 'T12:00:00');
        const sun = new Date(date);
        sun.setDate(date.getDate() - date.getDay());
        const sat = new Date(sun);
        sat.setDate(sun.getDate() + 6);
        const key = localDateKey(sun);
        if (!grouped[key]) {
            grouped[key] = { label: `${sun.getMonth() + 1}/${sun.getDate()} – ${sat.getMonth() + 1}/${sat.getDate()}`, values: [] };
            order.push(key);
        }
        grouped[key].values.push(item.value);
    });
    const rows = order.sort().map(key => ({ label: grouped[key].label, avg: grouped[key].values.reduce((a, b) => a + b, 0) / grouped[key].values.length }));
    rows.forEach((row, i) => { row.diff = i > 0 ? row.avg - rows[i - 1].avg : null; });
    const unit = appState.bodyProfile.unit || 'lbs';
    rows.reverse().forEach(row => {
        const tr = document.createElement('tr');
        const color = row.diff === null ? 'var(--faint)' : row.diff < 0 ? 'var(--brand)' : row.diff > 0 ? 'var(--protein)' : 'var(--muted)';
        tr.innerHTML = `
            <td class="muted">${row.label}</td>
            <td class="text-center"><b>${row.avg.toFixed(1)}</b> <span class="faint tiny">${unit}</span></td>
            <td class="text-right" style="color:${color};font-weight:700">${row.diff === null ? '—' : `${row.diff > 0 ? '+' : ''}${row.diff.toFixed(1)}`}</td>
        `;
        table.appendChild(tr);
    });
}
