function drawStrengthChart() {
    const canvas = document.getElementById('strength-chart-canvas');
    if (!canvas)
        return;
    const { ctx, w: W, h: H } = prepareCanvas(canvas);
    const data = getFilteredStrengthHistory();
    if (data.length < 2)
        return drawEmptyChart(ctx, W, H, 'Add two or more check-ins to see a trend');
    const padL = 64, padR = 16, padT = 16, padB = 16;
    const w = W - padL - padR, h = H - padT - padB;
    const getX = i => padL + (i / (data.length - 1)) * w;
    const getY = r => padT + h / 2 - r * (h / 2);
    const colorFor = r => r === 1 ? CHART.brand : r === -1 ? CHART.danger : CHART.warn;
    ctx.strokeStyle = CHART.grid;
    ctx.lineWidth = 1;
    [-1, 0, 1].forEach(r => { ctx.beginPath(); ctx.moveTo(padL, getY(r)); ctx.lineTo(padL + w, getY(r)); ctx.stroke(); });
    for (let i = 0; i < data.length - 1; i++) {
        ctx.beginPath();
        ctx.moveTo(getX(i), getY(data[i].rating));
        ctx.lineTo(getX(i + 1), getY(data[i + 1].rating));
        ctx.strokeStyle = colorFor(data[i + 1].rating);
        ctx.lineWidth = 2.5;
        ctx.stroke();
    }
    data.forEach((item, i) => { ctx.beginPath(); ctx.fillStyle = colorFor(item.rating); ctx.arc(getX(i), getY(item.rating), 4.5, 0, Math.PI * 2); ctx.fill(); });
    ctx.fillStyle = CHART.text;
    ctx.font = '11px "Plus Jakarta Sans", sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText('Stronger', padL - 8, getY(1) + 4);
    ctx.fillText('Same', padL - 8, getY(0) + 4);
    ctx.fillText('Weaker', padL - 8, getY(-1) + 4);
}
