// --- GOAL WEIGHT ESTIMATOR ---
function calculateGoalEstimate() {
    const input = document.getElementById('goal-weight-input');
    const targetVal = parseFloat(input.value);
    if (!targetVal || targetVal <= 0) {
        showToast("Enter a valid goal weight.", true);
        return;
    }
    const unit = appState.bodyProfile.unit || 'lbs';
    const history = (appState.weightHistory || []).slice().sort((a, b) => a.date.localeCompare(b.date));
    const currentWeight = history.length ? history[history.length - 1].value : (appState.bodyProfile.weight || 165);
    const diff = currentWeight - targetVal;
    const diffAbs = Math.abs(diff);
    appState.goalWeight = targetVal;
    saveStateToLocalStorage();
    drawWeightChart();
    document.getElementById('goal-current-weight').innerText = `${currentWeight.toFixed(1)} ${unit}`;
    document.getElementById('goal-target-weight').innerText = `${targetVal.toFixed(1)} ${unit}`;
    const diffEl = document.getElementById('goal-weight-diff');
    diffEl.innerText = diff === 0 ? 'Goal reached!' : `${diffAbs.toFixed(1)} ${unit} to ${diff > 0 ? 'lose' : 'gain'}`;
    const heightCm = (((appState.bodyProfile.heightFt || 5) * 12) + (appState.bodyProfile.heightIn || 10)) * 2.54;
    const weightKg = unit === 'lbs' ? currentWeight * 0.453592 : currentWeight;
    const age = appState.bodyProfile.age || 25;
    const bmr = 10 * weightKg + 6.25 * heightCm - 5 * age + ((appState.bodyProfile.sex || 'male') === 'male' ? 5 : -161);
    const multipliers = { sedentary: 1.2, light: 1.375, moderate: 1.55, very: 1.725, extreme: 1.9 };
    const tdee = bmr * (multipliers[appState.bodyProfile.activityLevel] || 1.55);
    const dailyDelta = tdee - (appState.targets.calories || 2000);
    let ratePerWeek = 0;
    if (history.length >= 2) {
        const recent = history.slice(-14);
        const days = (new Date(recent[recent.length - 1].date).getTime() - new Date(recent[0].date).getTime()) / 86400000;
        const change = recent[recent.length - 1].value - recent[0].value;
        // Only use the observed rate when it moves toward the goal.
        if (days >= 7 && Math.sign(change) === -Math.sign(diff))
            ratePerWeek = Math.abs(change) / (days / 7);
    }
    if (ratePerWeek <= 0.05 && Math.sign(dailyDelta) === Math.sign(diff)) {
        ratePerWeek = Math.abs(dailyDelta) * 7 / 3500;
        if (unit === 'kg')
            ratePerWeek *= 0.453592;
    }
    let etaText;
    if (diffAbs === 0)
        etaText = 'Achieved';
    else if (ratePerWeek <= 0.05)
        etaText = diff > 0 ? 'Not on track — your target is at or above maintenance' : 'Not on track — your target is at or below maintenance';
    else {
        const totalDays = Math.round((diffAbs / ratePerWeek) * 7);
        const targetDate = new Date();
        targetDate.setDate(targetDate.getDate() + totalDays);
        const formatted = targetDate.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        etaText = totalDays > 365 ? `~${(totalDays / 365).toFixed(1)} years (${formatted})` : totalDays > 60 ? `~${Math.round(totalDays / 30)} months (${formatted})` : `~${totalDays} days (${formatted})`;
    }
    document.getElementById('goal-eta').innerText = etaText;
    document.getElementById('goal-weight-result').classList.remove('hidden');
}
