function renderCalorieTrends() {
    calculateCalorieTrendStats();
    drawCalorieTrendChart();
    renderCalorieHeatmap();
}
function calculateCalorieTrendStats() {
    const days = appState.progressRange || 30;
    let totalLogged = 0;
    let loggedDaysCount = 0;
    for (let i = 0; i < days; i++) {
        const dayCal = dayTotals(localDateKey(localDayOffset(-i))).calories;
        if (dayCal > 0) {
            totalLogged += dayCal;
            loggedDaysCount++;
        }
    }
    const avg = loggedDaysCount > 0 ? Math.round(totalLogged / loggedDaysCount) : 0;
    document.getElementById('cal-trend-avg').innerText = `Avg: ${avg} kcal / day`;
}
function drawCalorieTrendChart() {
    const el = document.getElementById('calorie-trend-chart');
    if (!el)
        return;
    const days = appState.progressRange || 30;
    const series = dailySeries(days);
    if (!series.some(d => d.kcal > 0)) {
        el.innerHTML = chartEmpty('fa-chart-column', 'No food logged in this period yet.');
        return;
    }
    // Rolling 7-day average over logged days, once there are 3 of them.
    const rolling = series.map((d, i) => {
        const win = series.slice(Math.max(0, i - 6), i + 1).filter(x => x.kcal > 0);
        return win.length >= 3 ? win.reduce((sum, x) => sum + x.kcal, 0) / win.length : NaN;
    });
    el.innerHTML = barChartSvg({
        width: chartWidthOf(el), height: 200,
        bars: series.map(d => ({ ...d, segments: macroSegments(d), selected: d.key === localDateKey() })),
        goal: appState.targets.calories || 2000,
        lines: [{ values: rolling, color: 'var(--text)', width: 2 }]
    });
}
function renderCalorieHeatmap() {
    const grid = document.getElementById('weekly-cal-heatmap');
    if (!grid)
        return;
    grid.innerHTML = '';
    const target = appState.targets.calories || 2000;
    for (let i = 27; i >= 0; i--) {
        const date = localDayOffset(-i);
        const kcal = dayTotals(localDateKey(date)).calories;
        const pct = target > 0 ? kcal / target : 0;
        const box = document.createElement('div');
        if (kcal > 0)
            box.className = pct < 0.5 ? 'h1' : pct < 0.9 ? 'h2' : pct <= 1.05 ? 'h3' : 'h4';
        box.title = `${date.toLocaleDateString()}: ${kcal} kcal (${Math.round(pct * 100)}%)`;
        box.innerText = String(date.getDate());
        grid.appendChild(box);
    }
}
