// --- STREAK COUNTER ---
function calculateStreak() {
    const logDates = Object.keys(appState.dailyLogs || {}).filter(d => {
        const log = appState.dailyLogs[d];
        if (!log)
            return false;
        if (log.water && log.water > 0)
            return true;
        return Object.values(log.meals || {}).some(m => m && m.length > 0);
    }).sort();
    if (logDates.length === 0) {
        setStreakText(0, appState.bestStreak || 0);
        return;
    }
    const todayStr = localDateKey();
    const yesterdayStr = localDateKey(localDayOffset(-1));
    const hasToday = logDates.includes(todayStr);
    const hasYesterday = logDates.includes(yesterdayStr);
    let currentStreak = 0;
    if (hasToday || hasYesterday) {
        const checkDate = new Date((hasToday ? todayStr : yesterdayStr) + 'T12:00:00');
        while (logDates.includes(localDateKey(checkDate))) {
            currentStreak++;
            checkDate.setDate(checkDate.getDate() - 1);
        }
    }
    let maxContig = 0;
    let tempContig = 1;
    for (let i = 1; i < logDates.length; i++) {
        const diffDays = Math.round((new Date(logDates[i] + 'T12:00:00').getTime() - new Date(logDates[i - 1] + 'T12:00:00').getTime()) / 86400000);
        if (diffDays === 1)
            tempContig++;
        else if (diffDays > 1) {
            maxContig = Math.max(maxContig, tempContig);
            tempContig = 1;
        }
    }
    maxContig = Math.max(maxContig, tempContig);
    const bestStreak = Math.max(appState.bestStreak || 0, currentStreak, maxContig);
    appState.bestStreak = bestStreak;
    setStreakText(currentStreak, bestStreak);
}
// --- MACRO SPLIT DONUT ---
function renderMacroPieChart(pGrams, cGrams, fGrams) {
    const kcalP = pGrams * 4, kcalC = cGrams * 4, kcalF = fGrams * 9;
    const total = kcalP + kcalC + kcalF;
    const pctP = total > 0 ? Math.round((kcalP / total) * 100) : 0;
    const pctC = total > 0 ? Math.round((kcalC / total) * 100) : 0;
    const pctF = total > 0 ? Math.max(0, 100 - pctP - pctC) : 0;
    document.getElementById('pie-protein-pct').innerText = pctP;
    document.getElementById('pie-carbs-pct').innerText = pctC;
    document.getElementById('pie-fats-pct').innerText = pctF;
    const el = document.getElementById('ins-split-donut');
    if (el)
        el.innerHTML = donutSvg([{ value: kcalP, color: 'var(--protein)' }, { value: kcalC, color: 'var(--carbs)' }, { value: kcalF, color: 'var(--fat)' }]);
}
// --- CONFETTI ANIMATION CELEBRATION ---
function triggerConfetti() {
    const confettiContainer = document.createElement('div');
    confettiContainer.className = "fixed inset-0 pointer-events-none overflow-hidden";
    confettiContainer.style.zIndex = 95;
    document.body.appendChild(confettiContainer);
    const colors = ['#34d399', '#60a5fa', '#fbbf24', '#fb7185', '#a78bfa'];
    for (let i = 0; i < 60; i++) {
        const particle = document.createElement('div');
        particle.className = "confetti-particle";
        particle.style.left = Math.random() * 100 + 'vw';
        particle.style.top = '-5vh';
        const size = Math.random() * 8 + 5;
        particle.style.width = size + 'px';
        particle.style.height = size + 'px';
        particle.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
        particle.style.borderRadius = Math.random() > 0.5 ? '50%' : '20%';
        particle.style.animation = `confetti-fall ${Math.random() * 1.5 + 1.5}s ease-out ${Math.random() * 1.2}s forwards`;
        confettiContainer.appendChild(particle);
    }
    setTimeout(() => confettiContainer.remove(), 4500);
    showToast('🎯 You hit your calorie target for the day!');
}
// OVERLAY STACK (sheets, full-screen panels, scanner)
const overlayStack = [];
function showOverlay(id) {
    const el = document.getElementById(id);
    el.classList.remove('hidden');
    // Sheets opened from the scanner (batch adjust, create food, settings) sit above it.
    if (id !== 'modal-scanner' && isOverlayOpen('modal-scanner'))
        el.classList.add('over-scanner');
    const existing = overlayStack.indexOf(id);
    if (existing >= 0)
        overlayStack.splice(existing, 1);
    overlayStack.push(id);
    document.body.classList.add('has-overlay');
}
function hideOverlay(id) {
    document.getElementById(id).classList.add('hidden');
    document.getElementById(id).classList.remove('over-scanner');
    const existing = overlayStack.indexOf(id);
    if (existing >= 0)
        overlayStack.splice(existing, 1);
    if (overlayStack.length === 0)
        document.body.classList.remove('has-overlay');
}
function isOverlayOpen(id) {
    return overlayStack.includes(id);
}
function setSegActive(segId, value) {
    const seg = document.getElementById(segId);
    if (!seg || !seg.querySelectorAll)
        return;
    seg.querySelectorAll('button').forEach(btn => {
        const active = btn.dataset.meal === value;
        btn.classList.toggle('is-active', active);
        btn.setAttribute('aria-pressed', String(active));
    });
}
function prefersPointer() {
    return typeof window.matchMedia === 'function' && window.matchMedia('(pointer: fine)').matches;
}
