    aiResultsState.items.forEach((food, i) => {
        if (aiResultsState.selected[i])
            total += food.calories;
        const row = document.createElement('div');
        row.className = 'ai-item';
        row.innerHTML = `
            <input type="checkbox" ${aiResultsState.selected[i] ? 'checked' : ''} aria-label="Include ${escapeHTML(food.name)}">
            <button type="button" class="flex-1 min-w-0 text-left">
                <p class="font-semibold">${escapeHTML(food.name)}</p>
                <p class="small muted">${formatAmount(food.servingSize)} ${escapeHTML(food.servingUnit)} · P ${food.protein}g · C ${food.carbs}g · F ${food.fats}g</p>
            </button>
            <div class="result-kcal"><b>${food.calories}</b><span>kcal</span></div>
        `;
        row.querySelector('input').onchange = e => { aiResultsState.selected[i] = e.target.checked; renderAiResults(); };
        row.querySelector('button').onclick = () => openFoodReview(food, {
            meal: aiResultsState.meal,
            confirmLabel: 'Update item',
            onConfirm: (portion, meal) => { aiResultsState.items[i] = portion; aiResultsState.meal = meal; renderAiResults(); }
        });
        list.appendChild(row);
    });
    const count = aiResultsState.selected.filter(Boolean).length;
    document.getElementById('ai-results-total').innerText = `${count} selected · ${total} kcal`;
    const btn = document.getElementById('ai-results-log-btn');
    btn.disabled = count === 0;
    btn.innerText = `Log ${count} to ${MEAL_LABELS[aiResultsState.meal].toLowerCase()}`;
