function openCustomFoodModal(prefill = null) {
    customFoodContext = prefill;
    const note = document.getElementById('custom-food-note');
    note.classList.add('hidden');
    note.innerHTML = '';
    if (prefill) {
        document.getElementById('custom-food-name').value = prefill.name || '';
        document.getElementById('custom-food-brand').value = prefill.brand || '';
        document.getElementById('custom-food-barcode').value = prefill.barcode || '';
        const fromLabel = prefill.calories !== undefined;
        if (fromLabel) {
            document.getElementById('custom-food-size').value = formatAmount(prefill.servingSize || 100);
            document.getElementById('custom-food-unit').value = prefill.servingUnit === 'ml' ? 'ml' : 'g';
            ['calories', 'protein', 'carbs', 'fats'].forEach(k => { document.getElementById(`custom-food-${k}`).value = formatAmount(prefill[k] || 0); });
            Object.entries(prefill.micros || {}).forEach(([m, v]) => {
                const input = document.getElementById(`custom-micro-${m}`);
                if (input)
                    input.value = formatAmount(Number(v));
            });
            const lines = [`Read from your photo by AI${prefill.servingLabel ? ` · serving: ${prefill.servingLabel}` : ''}. Compare with the label before saving.`, ...(prefill.aiWarnings || [])];
            note.className = `note ${prefill.aiWarnings?.length ? '' : 'ai'}`;
            note.innerHTML = `<i class="fa-solid ${prefill.aiWarnings?.length ? 'fa-triangle-exclamation' : 'fa-wand-magic-sparkles'}"></i><span>${lines.map(escapeHTML).join('<br>')}</span>`;
        }
    }
    showOverlay('modal-custom-food');
    const focusId = !prefill ? 'custom-food-name' : !prefill.name ? 'custom-food-name' : prefill.calories === undefined ? 'custom-food-calories' : null;
    if (focusId && (prefersPointer() || prefill))
        document.getElementById(focusId).focus();
}
function closeCustomFoodModal() {
    hideOverlay('modal-custom-food');
    customFoodContext = null;
    ['name', 'brand', 'barcode', 'calories', 'protein', 'carbs', 'fats'].forEach(k => document.getElementById(`custom-food-${k}`).value = '');
    document.getElementById('custom-food-size').value = '100';
    document.getElementById('custom-food-unit').value = 'g';
    document.getElementById('custom-food-note').classList.add('hidden');
    CUSTOM_MICROS.forEach(m => { document.getElementById(`custom-micro-${m}`).value = ''; });
}
let isCustomMicrosOpen = false;
function toggleCustomMicrosSection() {
    isCustomMicrosOpen = !isCustomMicrosOpen;
    document.getElementById('custom-micros-content').classList.toggle('hidden', !isCustomMicrosOpen);
    document.getElementById('custom-micros-chevron').style.transform = isCustomMicrosOpen ? 'rotate(180deg)' : '';
    const toggle = document.getElementById('custom-micros-toggle');
    if (toggle.setAttribute)
        toggle.setAttribute('aria-expanded', String(isCustomMicrosOpen));
}
function saveCustomFood() {
    const name = document.getElementById('custom-food-name').value.trim();
    const brand = document.getElementById('custom-food-brand').value.trim();
    const barcode = document.getElementById('custom-food-barcode').value.replace(/\D/g, '');
    const size = parseFloat(document.getElementById('custom-food-size').value);
    const calories = parseFloat(document.getElementById('custom-food-calories').value);
    if (!name)
        return showToast("Enter a name for the food.", true);
    if (!(size > 0))
        return showToast("Serving size must be greater than zero.", true);
    if (!(calories >= 0))
        return showToast("Enter the calories per serving.", true);
    const micros = {};
    CUSTOM_MICROS.forEach(m => {
        const val = parseFloat(document.getElementById(`custom-micro-${m}`).value);
        micros[m] = (!isNaN(val) && val >= 0) ? val : 0;
    });
    const foodItem = {
        id: 'custom_' + Date.now(),
        name,
        store: brand || 'Custom',
        brand,
        barcode,
        calories: Math.round(calories),
        protein: Math.round((parseFloat(document.getElementById('custom-food-protein').value) || 0) * 10) / 10,
        carbs: Math.round((parseFloat(document.getElementById('custom-food-carbs').value) || 0) * 10) / 10,
        fats: Math.round((parseFloat(document.getElementById('custom-food-fats').value) || 0) * 10) / 10,
        servingSize: size,
        servingUnit: document.getElementById('custom-food-unit').value,
        micros,
        type: 'Custom Import'
    };
    const ctx = customFoodContext;
    if (ctx?.servingLabel && Number(ctx.servingSize) === size && foodItem.servingUnit === ctx.servingUnit) {
        foodItem.servingLabel = ctx.servingLabel;
        foodItem.servingQuantity = size;
    }
    if (!appState.customPacks)
        appState.customPacks = [];
    if (barcode)
        appState.customPacks = appState.customPacks.filter(f => f.barcode !== barcode);
    appState.customPacks.push(foodItem);
    saveStateToLocalStorage();
    const meal = customFoodContext?.meal || currentSearchMealSlot;
    const onSaved = customFoodContext?.onSaved;
    closeCustomFoodModal();
    showToast(`Saved "${name}" to My foods.`);
    if (onSaved)
        onSaved(foodItem);
    else
        openFoodReview(foodItem, { meal, closeSearchOnAdd: true });
    if (isOverlayOpen('modal-food-search'))
        renderOftenLoggedSection();
}
// NUTRITION LABEL + DIARY PORTION EDITOR
let activeDiaryPortion = null;
function previewDiaryPortion() {
    if (!activeDiaryPortion)
        return;
    try {
        const food = scaleFoodPortion(activeDiaryPortion.food, Number(document.getElementById('label-portion-amount').value));
        renderNutritionLabel(food);
        document.getElementById('label-portion-error').textContent = '';
        document.getElementById('label-portion-save').disabled = false;
    }
    catch (error) {
        document.getElementById('label-portion-error').textContent = error.message;
        document.getElementById('label-portion-save').disabled = true;
    }
}
function saveDiaryPortion() {
    if (!activeDiaryPortion)
        return;
    const { date, meal, id, food } = activeDiaryPortion;
    const entries = appState.dailyLogs[date]?.meals?.[meal];
    const index = entries?.findIndex(entry => entry.id === id) ?? -1;
    if (index < 0) {
        showToast('This diary entry is no longer available.', true);
        closeNutritionFactsModal();
        return;
    }
    let updated;
    try {
        updated = scaleFoodPortion(food, Number(document.getElementById('label-portion-amount').value));
    }
    catch (error) {
        document.getElementById('label-portion-error').textContent = error.message;
        return;
    }
    const targetMeal = activeDiaryPortion.targetMeal || meal;
    if (targetMeal !== meal && MEAL_KEYS.includes(targetMeal)) {
        entries.splice(index, 1);
        ensureDayLog(date).meals[targetMeal].push(updated);
    }
    else {
        entries[index] = updated;
    }
    saveStateToLocalStorage();
    closeNutritionFactsModal();
    renderAll();
    showToast(targetMeal !== meal ? `Moved to ${MEAL_LABELS[targetMeal].toLowerCase()}.` : 'Entry updated.');
}
function openNutritionLabel(food, diaryContext = null) {
    showOverlay('modal-nutrition-facts');
    activeDiaryPortion = diaryContext ? { ...diaryContext, food: JSON.parse(JSON.stringify(food)) } : null;
    document.getElementById('label-portion-controls').classList.toggle('hidden', !activeDiaryPortion);
    document.getElementById('label-entry-actions').classList.toggle('hidden', !activeDiaryPortion);
    document.getElementById('label-meal-field').classList.toggle('hidden', !activeDiaryPortion);
    if (activeDiaryPortion)
        setSegActive('label-meal-seg', activeDiaryPortion.meal);
    document.getElementById('label-portion-error').textContent = '';
    document.getElementById('label-portion-save').disabled = false;
    if (activeDiaryPortion) {
        document.getElementById('label-portion-amount').value = food.servingSize;
        document.getElementById('label-portion-unit').textContent = food.servingUnit;
    }
    renderNutritionLabel(food);
    if (activeDiaryPortion && prefersPointer())
        document.getElementById('label-portion-amount').focus();
}
function renderNutritionLabel(food) {
    document.getElementById('label-food-name').innerText = food.name;
    const brand = food.store && !/^(Generic|Generic Staple|Manual Entry|Custom)$/i.test(food.store) ? food.store : '';
    document.getElementById('label-food-brand').innerText = [brand, food.barcode ? `Barcode ${food.barcode}` : ''].filter(Boolean).join(' · ');
    document.getElementById('label-serving-display').innerText = `${formatAmount(food.servingSize)} ${food.servingUnit}`;
    document.getElementById('label-calories').innerText = food.calories;
    document.getElementById('label-fat').innerText = food.fats;
    document.getElementById('label-carbs').innerText = food.carbs;
    document.getElementById('label-protein').innerText = food.protein;
    document.getElementById('label-fat-pct').innerText = Math.round((food.fats / (appState.targets.fats || 1)) * 100);
    document.getElementById('label-carbs-pct').innerText = Math.round((food.carbs / (appState.targets.carbs || 1)) * 100);
    document.getElementById('label-protein-pct').innerText = Math.round((food.protein / (appState.targets.protein || 1)) * 100);
    const container = document.getElementById('label-micros-panel');
    container.innerHTML = '';
    let shown = 0;
    if (food.micros) {
        micronutrients.forEach(m => {
            const val = food.micros[m.id] || 0;
            if (val > 0) {
                shown++;
                const pct = Math.round((val / (appState.targets[m.targetKey] || 1)) * 100);
                const div = document.createElement('div');
                div.className = "row";
                div.innerHTML = `<span>${escapeHTML(m.name)}</span><span>${val < 10 ? val.toFixed(2) : val.toFixed(1)} ${m.unit} <span class="faint">· ${pct}%</span></span>`;
                container.appendChild(div);
            }
        });
    }
    if (!shown) {
        const p = document.createElement('p');
        p.className = 'small faint py-2';
        p.innerText = 'No vitamin or mineral data for this food.';
        container.appendChild(p);
    }
}
