let activeVisionImage = null;
function triggerVisionUpload(meal) {
    if (MEAL_KEYS.includes(meal))
        currentSearchMealSlot = meal;
    if (!requireGemini())
        return;
    const input = document.getElementById('vision-file-input');
    input.value = '';
    input.click();
}
function loadImageFromFile(file) {
    return new Promise((resolve, reject) => {
        const url = URL.createObjectURL(file);
        const img = new Image();
        img.onload = () => resolve({ img, url });
        img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('That image could not be opened. Try a JPEG or PNG.')); };
        img.src = url;
    });
}
async function downscaleImage(file, maxSide = 1280, quality = 0.85) {
    const { img, url } = await loadImageFromFile(file);
    try {
        const scale = Math.min(1, maxSide / Math.max(img.naturalWidth, img.naturalHeight));
        const canvas = document.createElement('canvas');
        canvas.width = Math.round(img.naturalWidth * scale);
        canvas.height = Math.round(img.naturalHeight * scale);
        canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg', quality);
        return { dataUrl, base64: dataUrl.split(',')[1], mimeType: 'image/jpeg' };
    }
    finally {
        URL.revokeObjectURL(url);
    }
}
async function processVisionUpload(event) {
    const file = event.target.files[0];
    if (!file)
        return;
    try {
        activeVisionImage = await downscaleImage(file);
        document.getElementById('vision-preview-img').src = activeVisionImage.dataUrl;
        showOverlay('modal-vision-confirm');
    }
    catch (e) {
        showToast(e.message, true);
    }
}
function openVisionConfirmModal() {
    showOverlay('modal-vision-confirm');
}
function closeVisionConfirmModal() {
    hideOverlay('modal-vision-confirm');
    document.getElementById('vision-confirm-description').value = '';
    activeVisionImage = null;
}
async function executeVisionScan() {
    if (!activeVisionImage || !requireGemini())
        return;
    const desc = document.getElementById('vision-confirm-description').value.trim();
    const btn = document.getElementById('vision-confirm-btn');
    const original = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-circle-notch spin"></i><span>Analyzing photo…</span>';
    try {
        const food = await queryGeminiVisionAI(activeVisionImage.base64, activeVisionImage.mimeType, desc);
        closeVisionConfirmModal();
        openFoodReview(food, { meal: currentSearchMealSlot, closeSearchOnAdd: true });
    }
    catch (e) {
        console.error("Vision AI failed:", e);
        showToast(e.message || 'Could not analyze that photo.', true);
    }
    finally {
        btn.disabled = false;
        btn.innerHTML = original;
    }
}
// =========================================================================
// BARCODE SCANNER
// Live camera via getUserMedia. Decodes with the native BarcodeDetector
// when the browser has one (Android Chrome, Safari 17+ on macOS), and
// otherwise with ZXing loaded on demand. A code is accepted only when its
// GTIN check digit is valid and it was read in two separate frames.
// =========================================================================
const ZXING_URL = 'https://cdn.jsdelivr.net/npm/@zxing/library@0.21.3/umd/index.min.js';
// ZXing-C++ compiled to WebAssembly (BarcodeDetector ponyfill). Reads UPC-E and
// damaged/blurred codes that the JavaScript ZXing port misses.
const BARCODE_WASM_URL = 'https://cdn.jsdelivr.net/npm/barcode-detector@3.2.2/dist/iife/ponyfill.min.js';
const CAMERA_PREF_KEY = 'macroflow_scanner_camera';
const SCAN_HINT = 'Hold the phone about 15–20 cm (6–8 in) away so the camera can focus, with the barcode inside the frame.';
const RETAIL_FORMATS = ['ean_13', 'ean_8', 'upc_a', 'upc_e'];
const SCAN_CONFIRMATIONS = 2;
const SCAN_WINDOW_MS = 1500;
const scanner = {
    session: 0,
    stream: null,
    track: null,
    running: false,
    busy: false,
    timer: null,
    decoder: null,
    reads: [],
    torchOn: false,
    canvas: null,
    frames: 0,
    devices: [],
    zoomLevels: [],
    zoomIndex: 0,
    batch: false, // keep the camera on and log several products in a row
    batchCount: 0,
    ignoreCode: null, // the product just handled, ignored briefly after resuming
    ignoreUntil: 0,
    lastPhoto: null,
    autoLensDone: false
};
const BATCH_IGNORE_MS = 3000;
// Exact GTIN match in USDA Branded Foods, or null.
async function lookupUsdaBarcode(rawCode, fetchImpl) {
    const spellings = usdaGtinSpellings(rawCode);
    const wanted = new Set(spellings.map(c => c.replace(/^0+/, '')));
    const url = `https://api.nal.usda.gov/fdc/v1/foods/search?api_key=${encodeURIComponent(getUsdaKey({ allowDemo: true }))}&dataType=Branded&requireAllWords=false&pageSize=10&query=${encodeURIComponent(spellings.join(' '))}`;
    const res = await fetchImpl(url, { headers: { Accept: 'application/json' } });
    if (res.status === 429)
        throw new Error('USDA lookup limit reached');
    if (!res.ok)
        throw new Error(`USDA error ${res.status}`);
    const data = await res.json();
    const hit = (data.foods || []).find(f => f.gtinUpc && wanted.has(String(f.gtinUpc).replace(/\D/g, '').replace(/^0+/, '')));
    return hit ? foodFromUsdaBranded(hit, cleanBarcode(rawCode)) : null;
}
// --- Product lookup -------------------------------------------------------
// Exact barcode lookup only: My foods, then Open Food Facts, then USDA Branded
// Foods, then the offline copy. Never guesses: an unknown code is reported as
// "not found" so the user can add it from the label.
async function lookupBarcode(rawCode, { fetchImpl = (u, o) => fetchWithTimeout(u, o, 10000) } = {}) {
    const candidates = barcodeCandidates(rawCode);
    const custom = (appState.customPacks || []).find(f => f.barcode && candidates.includes(cleanBarcode(f.barcode)));
    if (custom)
        return { status: 'found', food: { ...custom, type: 'Custom Import' }, source: 'custom' };
    let networkError = null;
    let partial = null; // in Open Food Facts but without nutrition facts
    for (const code of candidates) {
        try {
            const res = await fetchImpl(`https://world.openfoodfacts.org/api/v2/product/${code}.json?fields=code,product_name,product_name_en,generic_name,brands,nutriments,serving_size,serving_quantity,serving_quantity_unit,image_front_small_url,image_small_url,quantity`, { headers: { Accept: 'application/json' } });
            if (res.status === 404)
                continue;
            if (!res.ok)
                throw new Error(`Open Food Facts error ${res.status}`);
            const data = await res.json();
            if (data && data.status === 1 && data.product) {
                const food = foodFromOpenFoodFactsProduct(data.product, code);
                if (!food.missingNutrition)
                    return { status: 'found', food, code, source: 'off' };
                partial = partial || { food, code };
            }
        }
        catch (err) {
            networkError = err;
        }
    }
    let usdaError = null;
    try {
        const food = await lookupUsdaBarcode(rawCode, fetchImpl);
        if (food)
            return { status: 'found', food, code: food.barcode, source: 'usda' };
    }
    catch (err) {
        usdaError = err;
    }
    for (const code of candidates) {
        const cached = appState.barcodeCache?.[code];
        if (cached)
            return { status: 'found', food: { ...cached }, code, fromCache: true };
    }
    if (partial)
        return { status: 'no_nutrition', food: partial.food, code: partial.code };
    if (networkError)
        return { status: 'error', code: candidates[0], message: typeof navigator !== 'undefined' && navigator.onLine === false ? 'You are offline.' : 'Could not reach Open Food Facts.' };
    return { status: 'not_found', code: candidates[0], usdaSkipped: Boolean(usdaError) };
}
// --- Decoders -------------------------------------------------------------
const scriptPromises = {};
function loadScriptGlobal(url, globalName) {
    if (window[globalName])
        return Promise.resolve(window[globalName]);
    if (!scriptPromises[url]) {
        scriptPromises[url] = new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = url;
            script.async = true;
            script.crossOrigin = 'anonymous';
            script.onload = () => window[globalName] ? resolve(window[globalName]) : reject(new Error('Barcode library failed to load.'));
            script.onerror = () => { delete scriptPromises[url]; reject(new Error('Could not download the barcode reader. Check your connection.')); };
            document.head.appendChild(script);
        });
    }
    return scriptPromises[url];
}
function loadZXing() {
    return loadScriptGlobal(ZXING_URL, 'ZXing');
}
function withTimeout(promise, ms, message) {
    let timer;
    return Promise.race([promise, new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(message)), ms); })])
        .finally(() => clearTimeout(timer));
}
function wrapDetector(kind, detector) {
    return {
        kind,
        async detect(source) {
            const found = await detector.detect(source);
            return found.map(b => ({ text: b.rawValue, format: b.format }));
        }
    };
}
async function createNativeDecoder() {
    if (!('BarcodeDetector' in window) || window.BarcodeDetector === window.BarcodeDetectionAPI?.BarcodeDetector)
        return null;
    try {
        const supported = await window.BarcodeDetector.getSupportedFormats();
        const formats = RETAIL_FORMATS.filter(f => supported.includes(f));
        if (formats.length < 2)
            return null;
        return wrapDetector('native', new window.BarcodeDetector({ formats }));
    }
    catch (e) {
        console.warn('Native BarcodeDetector unavailable.', e);
        return null;
    }
}
async function createWasmDecoder() {
    if (typeof WebAssembly === 'undefined')
        return null;
    try {
        const api = await loadScriptGlobal(BARCODE_WASM_URL, 'BarcodeDetectionAPI');
        const detector = new api.BarcodeDetector({ formats: RETAIL_FORMATS });
        // Warm up: downloads and compiles the .wasm now, so a failure falls back
        // to the JavaScript decoder instead of silently scanning nothing.
        const probe = document.createElement('canvas');
        probe.width = probe.height = 8;
        probe.getContext('2d').fillRect(0, 0, 8, 8);
        await withTimeout(detector.detect(probe), 20000, 'Barcode reader took too long to load.');
        return wrapDetector('wasm', detector);
    }
    catch (e) {
        console.warn('WebAssembly barcode reader unavailable, using ZXing JS.', e);
        return null;
    }
}
async function createZXingDecoder() {
    const ZX = await loadZXing();
    const hints = new Map();
    hints.set(ZX.DecodeHintType.POSSIBLE_FORMATS, [ZX.BarcodeFormat.EAN_13, ZX.BarcodeFormat.EAN_8, ZX.BarcodeFormat.UPC_A, ZX.BarcodeFormat.UPC_E]);
    hints.set(ZX.DecodeHintType.TRY_HARDER, true);
    const reader = new ZX.MultiFormatReader();
    reader.setHints(hints);
    const formatName = f => String(ZX.BarcodeFormat[f] || f).toLowerCase();
    return {
        kind: 'zxing',
        canvasOnly: true,
        async detect(canvas) {
            try {
                const source = new ZX.HTMLCanvasElementLuminanceSource(canvas);
                const result = reader.decodeWithState(new ZX.BinaryBitmap(new ZX.HybridBinarizer(source)));
                return [{ text: result.getText(), format: formatName(result.getBarcodeFormat()) }];
            }
            catch (e) {
                return [];
            }
            finally {
                reader.reset();
            }
        }
    };
}
// Best available: the phone's own detector, then ZXing-C++ (WebAssembly),
// then the JavaScript ZXing port for browsers without WebAssembly.
async function createBarcodeDecoder() {
    return (await createNativeDecoder()) || (await createWasmDecoder()) || (await createZXingDecoder());
}
