// Crop the part of the video that sits under the on-screen scan window.
function grabScanRegion(video, mode = 'window') {
    const vw = video.videoWidth, vh = video.videoHeight;
    if (!vw || !vh)
        return null;
    const rect = video.getBoundingClientRect();
    const win = document.getElementById('scanner-window').getBoundingClientRect();
    const scale = Math.max(rect.width / vw, rect.height / vh);
    const offX = (rect.width - vw * scale) / 2;
    const offY = (rect.height - vh * scale) / 2;
    let sx = (win.left - rect.left - offX) / scale;
    let sy = (win.top - rect.top - offY) / scale;
    let sw = win.width / scale;
    let sh = win.height / scale;
    // Generous margin: the barcode often overhangs the guide.
    sx -= sw * 0.1;
    sw *= 1.2;
    sy -= sh * 0.25;
    sh *= 1.5;
    sx = Math.max(0, sx);
    sy = Math.max(0, sy);
    sw = Math.min(vw - sx, sw);
    sh = Math.min(vh - sy, sh);
    if (mode === 'band') {
        sx = 0;
        sw = vw;
        sy = Math.max(0, sy - sh * 0.25);
        sh = Math.min(vh - sy, sh * 1.5);
    }
    if (mode === 'full') {
        sx = 0;
        sy = 0;
        sw = vw;
        sh = vh;
    }
    if (sw < 40 || sh < 20) {
        sx = 0;
        sy = 0;
        sw = vw;
        sh = vh;
    }
    const outScale = Math.min(1, 1280 / Math.max(sw, mode === 'full' ? sh : 0));
    if (!scanner.canvas)
        scanner.canvas = document.createElement('canvas');
    const canvas = scanner.canvas;
    canvas.width = Math.round(sw * outScale);
    canvas.height = Math.round(sh * outScale);
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    ctx.drawImage(video, sx, sy, sw, sh, 0, 0, canvas.width, canvas.height);
    return canvas;
}
