    document.getElementById('health-calories-kind').value = summary.caloriesKind || 'total';
    document.getElementById('health-weight-field').classList.toggle('hidden', !summary.counts.weight);
    document.getElementById('health-weight-unit').value = summary.weightUnit || 'kg';
    const latest = Object.keys(summary.days).sort().reverse().slice(0, 3).map(date => {
        const v = summary.days[date];
        return `<div class="row"><span>${fmt(date)}</span><span>${[v.steps !== undefined ? `${Math.round(v.steps).toLocaleString('en-US')} steps` : '', (v.calories ?? v.total ?? v.active) !== undefined ? `${Math.round(v.calories ?? v.total ?? v.active).toLocaleString('en-US')} kcal` : '', v.weight !== undefined ? `${v.weight} ${summary.weightUnit}` : ''].filter(Boolean).join(' · ')}</span></div>`;
    }).join('');
