function addWater(liters) {
    const log = ensureDayLog();
    log.water = Math.max(0, Math.round(((log.water || 0) + liters) * 1000) / 1000);
    saveStateToLocalStorage();
    renderWaterSection();
    calculateStreak();
    renderWeekStrip();
}
function renderWaterSection() {
    const target = Number(appState.targets.water) || 2.5;
    const water = getDayLog().water || 0;
    document.getElementById('water-amount').innerText = `${formatAmount(water)} of ${formatAmount(target)} L`;
    // One glass per 250 ml of the target.
    const glasses = Math.max(4, Math.min(12, Math.round(target / 0.25)));
    const full = Math.min(glasses, Math.round(water / 0.25));
    document.getElementById('water-glasses').innerHTML = Array.from({ length: glasses }, (_, i) => `<span class="${i < full ? 'full' : ''}"></span>`).join('');
    document.getElementById('water-minus').disabled = water <= 0;
}
