// WEEKLY REPORT (Insights)
// =========================================================================
function weeklyReport(endKey = localDateKey(), days = 7) {
    const end = new Date(endKey + 'T12:00:00');
    const rows = [];
    for (let i = days - 1; i >= 0; i--) {
        const d = new Date(end);
        d.setDate(end.getDate() - i);
        const key = localDateKey(d);
        const totals = dayTotals(key);
        rows.push({ key, ...totals, goal: dayGoal(key), steps: appState.activity?.[key]?.steps, burned: appState.activity?.[key]?.caloriesOut, exercise: exerciseCaloriesFor(key) });
    }
    return rustWasm.weeklyReportFromRows(rows, localDateKey());
}
function renderWeeklyReport() {
    const el = document.getElementById('weekly-report');
    if (!el)
        return;
    const r = weeklyReport();
    const fmt = n => Number(n).toLocaleString('en-US');
    const rows = [
        ['Days logged', `${r.daysLogged} of ${r.days}`],
        ['Average intake', r.daysLogged ? `${fmt(r.avgCalories)} kcal <span class="faint">/ ${fmt(r.avgGoal)} goal</span>` : '—'],
        ['Days within 10% of goal', r.daysLogged ? `${r.onTarget}` : '—'],
        ['Average protein', r.daysLogged ? `${r.avgProtein} g <span class="faint">/ ${appState.targets.protein} g</span>` : '—']
    ];
    if (r.totalExercise)
        rows.push(['Exercise', `${fmt(r.totalExercise)} kcal`]);
    if (r.avgSteps !== null)
        rows.push(['Average steps', fmt(r.avgSteps)]);
    if (r.avgBalance !== null)
        rows.push(['Average energy balance', `${r.avgBalance > 0 ? '+' : '−'}${fmt(Math.abs(r.avgBalance))} kcal/day <span class="faint">${r.avgBalance > 0 ? 'surplus' : 'deficit'}</span>`]);
    el.innerHTML = rows.map(([k, v]) => `<div class="row"><span>${k}</span><span>${v}</span></div>`).join('')
        + (appState.lastHealthSync ? `<p class="small faint pt-3"><i class="fa-brands fa-apple"></i> ${escapeHTML(healthSyncStatusText())}</p>` : '');
}
