async function testGeminiKey() {
    if (!requireGemini())
        return;
    const btn = document.getElementById('gemini-test-btn');
    const original = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-circle-notch spin"></i>Testing…';
    try {
        await callGemini([{ text: 'Reply with the JSON object {"ok": true}.' }], { timeoutMs: 20000 });
        showToast('Gemini is working.');
    }
    catch (e) {
        showToast(e.message, true);
    }
    finally {
        btn.disabled = false;
        btn.innerHTML = original;
    }
}
