function readNumber(id, fallback, { min = -Infinity, max = Infinity, integer = false } = {}) {
    const raw = parseFloat(document.getElementById(id).value);
    if (!Number.isFinite(raw))
        return fallback;
    const clamped = Math.min(max, Math.max(min, raw));
    return integer ? Math.round(clamped) : clamped;
}
function closeSettingsModal() {
    const t = appState.targets;
    t.calories = readNumber('settings-target-cal', t.calories || 2000, { min: 500, max: 10000, integer: true });
    t.protein = readNumber('settings-target-protein', t.protein || 150, { min: 0, max: 600, integer: true });
    t.carbs = readNumber('settings-target-carbs', t.carbs || 200, { min: 0, max: 1500, integer: true });
    t.fats = readNumber('settings-target-fats', t.fats || 65, { min: 0, max: 400, integer: true });
    t.water = readNumber('settings-target-water', t.water || 2.5, { min: 0.5, max: 10 });
    const p = appState.bodyProfile;
    p.unit = document.getElementById('settings-weight-unit').value;
    p.sex = document.getElementById('settings-profile-sex').value;
    p.age = readNumber('settings-profile-age', p.age || 25, { min: 13, max: 100, integer: true });
    p.heightFt = readNumber('settings-profile-height-ft', p.heightFt || 5, { min: 3, max: 8, integer: true });
    p.heightIn = readNumber('settings-profile-height-in', p.heightIn ?? 10, { min: 0, max: 11, integer: true });
    p.weight = readProfileWeightLbs(p.weight || 165);
    p.activityLevel = document.getElementById('settings-profile-activity').value;
    p.goal = document.getElementById('settings-profile-goal').value;
    appState.settings = { ...(appState.settings || {}), exerciseAddsToGoal: document.getElementById('settings-exercise-goal').checked };
    if (!document.getElementById('form-micros-panel').classList.contains('hidden')) {
        micronutrients.forEach(m => {
            const input = document.getElementById(`form-micro-${m.id}`);
            if (input)
                appState.targets[m.targetKey] = parseFloat(input.value) || 0;
        });
    }
    hideOverlay('modal-settings');
    renderAll();
    if (appState.activeTab === 'progress')
        setProgressSubTab(appState.progressSubTab);
    if (appState.activeTab === 'dashboard')
        renderDashboardTab();
    saveStateToLocalStorage();
    showToast("Settings saved.");
}
