// TDEE AUTO-CALCULATOR
// The Settings weight field shows the unit picked under "Weight unit".
function settingsWeightUnit() {
    return document.getElementById('settings-weight-unit').value === 'kg' ? 'kg' : 'lbs';
}
function showProfileWeight(weightLbs, unit = settingsWeightUnit()) {
    const input = document.getElementById('settings-profile-weight');
    document.getElementById('settings-profile-weight-label').innerText = `Weight ${unit}`;
    input.value = unit === 'kg' ? Math.round((weightLbs / LB_PER_KG) * 10) / 10 : Math.round(weightLbs * 10) / 10;
    input.min = unit === 'kg' ? 27 : 60;
    input.max = unit === 'kg' ? 320 : 700;
}
function readProfileWeightLbs(fallbackLbs) {
    const kg = settingsWeightUnit() === 'kg';
    const value = readNumber('settings-profile-weight', NaN, kg ? { min: 27, max: 320 } : { min: 60, max: 700 });
    if (!Number.isFinite(value))
        return fallbackLbs;
    return kg ? Math.round(value * LB_PER_KG * 10) / 10 : value;
}
// Switching the unit converts the number already in the field.
function onSettingsWeightUnitChange() {
    const input = document.getElementById('settings-profile-weight');
    const wasKg = /kg/.test(document.getElementById('settings-profile-weight-label').innerText);
    const value = parseFloat(input.value);
    const lbs = Number.isFinite(value) ? (wasKg ? value * LB_PER_KG : value) : (appState.bodyProfile.weight || 165);
    showProfileWeight(lbs);
}
