// The answers as a profile (weight in lb, height in ft/in), or null while incomplete.
function readWelcome() {
    const num = id => { const v = parseFloat(document.getElementById(id).value); return Number.isFinite(v) ? v : null; };
    const age = num('welcome-age');
    let heightCm, weightLbs;
    if (welcomeUnits === 'metric') {
        heightCm = num('welcome-height-cm');
        const kg = num('welcome-weight-kg');
        weightLbs = kg ? kg * LB_PER_KG : null;
    }
    else {
        const ft = num('welcome-height-ft');
        heightCm = ft ? (ft * 12 + (num('welcome-height-in') || 0)) * 2.54 : null;
        weightLbs = num('welcome-weight-lb');
    }
    if (!(age >= 13 && age <= 100) || !(heightCm >= 120 && heightCm <= 230) || !(weightLbs >= 60 && weightLbs <= 700))
        return null;
    const totalIn = Math.round(heightCm / 2.54);
    return {
        sex: document.getElementById('welcome-sex').value,
        age: Math.round(age), heightCm,
        heightFt: Math.floor(totalIn / 12), heightIn: totalIn % 12,
        weightLbs: Math.round(weightLbs * 10) / 10,
        activity: document.getElementById('welcome-activity').value,
        goal: document.getElementById('welcome-goal').value,
        unit: welcomeUnits === 'metric' ? 'kg' : 'lbs'
    };
}
function renderWelcomePreview() {
    const box = document.getElementById('welcome-result');
    const answers = readWelcome();
    document.getElementById('welcome-apply').disabled = !answers;
    if (!answers) {
        box.innerHTML = '<p class="small muted">Enter your age, height and weight to see your targets.</p>';
        return null;
    }
    const r = computeTargets(answers);
    box.innerHTML = `<p class="small muted">Daily target · maintenance ≈ ${r.tdee.toLocaleString('en-US')} kcal</p>
        <p class="big">${r.calories.toLocaleString('en-US')} kcal</p>
        <p class="macros"><span>Protein <b>${r.protein} g</b></span><span>Carbs <b>${r.carbs} g</b></span><span>Fat <b>${r.fats} g</b></span></p>`;
    return r;
}
function applyWelcome() {
    const answers = readWelcome();
    if (!answers)
        return;
    const r = computeTargets(answers);
    Object.assign(appState.targets, { calories: r.calories, protein: r.protein, carbs: r.carbs, fats: r.fats });
    Object.assign(appState.bodyProfile, {
        sex: answers.sex, age: answers.age, heightFt: answers.heightFt, heightIn: answers.heightIn,
        weight: answers.weightLbs, activityLevel: answers.activity, goal: answers.goal, unit: answers.unit
    });
    appState.onboarded = true;
    saveStateToLocalStorage();
    closeWelcome();
    renderAll();
    showToast(`Targets set: ${r.calories.toLocaleString('en-US')} kcal · P ${r.protein} g · C ${r.carbs} g · F ${r.fats} g`);
}
