function calculateTDEETargets() {
    const sex = document.getElementById('settings-profile-sex').value;
    const age = readNumber('settings-profile-age', 25, { min: 13, max: 100, integer: true });
    const heightFt = readNumber('settings-profile-height-ft', 5, { min: 3, max: 8, integer: true });
    const heightIn = readNumber('settings-profile-height-in', 10, { min: 0, max: 11, integer: true });
    const weightLbs = readProfileWeightLbs(appState.bodyProfile.weight || 165);
    const activity = document.getElementById('settings-profile-activity').value;
    const goal = document.getElementById('settings-profile-goal').value;
    const r = computeTargets({ sex, age, heightCm: (heightFt * 12 + heightIn) * 2.54, weightLbs, activity, goal });
    Object.assign(appState.targets, { calories: r.calories, protein: r.protein, carbs: r.carbs, fats: r.fats });
    Object.assign(appState.bodyProfile, { sex, age, heightFt, heightIn, weight: weightLbs, activityLevel: activity, goal });
    appState.onboarded = true;
    document.getElementById('settings-target-cal').value = r.calories;
    document.getElementById('settings-target-protein').value = r.protein;
    document.getElementById('settings-target-carbs').value = r.carbs;
    document.getElementById('settings-target-fats').value = r.fats;
    const delta = r.calories - r.tdee;
    showToast(`Maintenance ≈ ${r.tdee} kcal (BMR ${r.bmr}).\nNew target: ${r.calories} kcal${delta ? ` (${delta > 0 ? '+' : ''}${delta})` : ''} · P ${r.protein}g · C ${r.carbs}g · F ${r.fats}g`, false, null, 7000);
    renderAll();
    saveStateToLocalStorage();
}
// DATA IMPORT / EXPORT
function downloadFile(filename, text, type = 'application/json') {
    const blob = new Blob([text], { type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function exportData() {
    downloadFile(`macroflow_backup_${localDateKey()}.json`, JSON.stringify(appState, null, 1));
    showToast("Backup downloaded.");
}
function triggerImport() {
    const input = document.getElementById('import-file-input');
    input.value = '';
    input.click();
}
function importData(event) {
    const file = event.target.files[0];
    if (!file)
        return;
    const reader = new FileReader();
    reader.onload = function (e) {
        let importedState;
        try {
            importedState = JSON.parse(String(e.target.result));
        }
        catch (err) {
            showToast("That file is not valid JSON.", true);
            return;
        }
        if (!importedState || typeof importedState !== 'object' || (!importedState.dailyLogs && !importedState.targets)) {
            showToast("That file doesn't look like a MacroFlow backup.", true);
            return;
        }
        const days = Object.keys(importedState.dailyLogs || {}).length;
        if (!confirm(`Import this backup (${days} logged day${days === 1 ? '' : 's'})? Matching days and settings on this device will be replaced.`))
            return;
        appState = { ...appState, ...importedState, currentDate: localDateKey() };
        ensureUniqueDiaryEntryIds();
        saveStateToLocalStorage();
        renderAll();
        showToast("Backup imported.");
    };
    reader.readAsText(file);
}
function clearStateData() {
    if (confirm("Erase all MacroFlow data in this browser? Export a backup first — this cannot be undone.")) {
        localStorage.removeItem(LOCAL_STORAGE_KEY);
        location.reload();
    }
}
// CLIPBOARD EXPORT DAY LOGS
function copyDayLog() {
    const date = appState.currentDate;
    const log = appState.dailyLogs[date];
    const hasItems = log && Object.values(log.meals || {}).some(m => m && m.length);
    if (!hasItems) {
        showToast("Nothing logged on this day yet.", true);
        return;
    }
    const totals = dayTotals(date);
    let text = `MacroFlow — ${formatDateShort(date)}\n`;
    MEAL_KEYS.forEach(meal => {
        const items = log.meals[meal] || [];
        if (!items.length)
            return;
        text += `\n${MEAL_LABELS[meal]}\n`;
        items.forEach(food => {
            text += `• ${food.name} (${formatAmount(food.servingSize)} ${food.servingUnit}) — ${food.calories} kcal, P ${food.protein}g, C ${food.carbs}g, F ${food.fats}g\n`;
        });
    });
    text += `\nTotal: ${totals.calories} kcal · P ${Math.round(totals.protein)}g · C ${Math.round(totals.carbs)}g · F ${Math.round(totals.fats)}g (goal ${appState.targets.calories} kcal)`;
    if (!navigator.clipboard?.writeText) {
        showToast("Copying isn't supported in this browser.", true);
        return;
    }
    navigator.clipboard.writeText(text)
        .then(() => showToast("Day summary copied."))
        .catch(() => showToast("Couldn't copy the summary.", true));
}
// TOASTS
function showToast(message, isError = false, action = null, durationMs = 0) {
    if (typeof isError === 'number') {
        durationMs = isError;
        isError = false;
    }
    const container = document.getElementById('toast-container');
    const toast = document.createElement('div');
    toast.className = `toast${isError ? ' error' : ''}`;
    toast.setAttribute && toast.setAttribute('role', isError ? 'alert' : 'status');
    toast.innerHTML = `
        <i class="fa-solid ${isError ? 'fa-circle-exclamation' : 'fa-circle-check'}"></i>
        <span class="toast-message"></span>
        <button class="toast-action hidden btn btn-sm btn-soft" style="width:auto;height:30px;min-height:30px;padding:0 10px"></button>
        <button class="toast-close" aria-label="Dismiss"><i class="fa-solid fa-xmark"></i></button>
    `;
    toast.querySelector('.toast-message').textContent = message;
    toast.querySelector('.toast-close').onclick = () => toast.remove();
    if (action) {
        const btn = toast.querySelector('.toast-action');
        btn.textContent = action.label;
        btn.classList.remove('hidden');
        btn.onclick = () => { toast.remove(); action.onClick(); };
    }
    container.appendChild(toast);
    const live = container.children ? Array.from(container.children) : [];
    if (live.length > 3)
        live.slice(0, live.length - 3).forEach((t) => t.remove());
    setTimeout(() => toast.remove(), durationMs || (action ? 6000 : isError ? 5000 : 3200));
}
// PRINT
function printReport() {
    hideOverlay('modal-settings');
    switchTab('nutrition');
    setTimeout(() => window.print(), 150);
}
// COPY PREVIOUS DAY'S MEALS
function copyYesterdayMeals() {
    const todayStr = appState.currentDate;
    const yesterdayDate = new Date(todayStr + 'T12:00:00');
    yesterdayDate.setDate(yesterdayDate.getDate() - 1);
    const yesterdayStr = localDateKey(yesterdayDate);
    const yesterdayLog = appState.dailyLogs[yesterdayStr];
    if (!yesterdayLog || !yesterdayLog.meals) {
        showToast("Nothing was logged the previous day.", true);
        return;
    }
    let copiedCount = 0;
    const log = ensureDayLog(todayStr);
    MEAL_KEYS.forEach(meal => {
        (yesterdayLog.meals[meal] || []).forEach(f => {
            const cloned = JSON.parse(JSON.stringify(f));
            cloned.id = createDiaryEntryId();
            cloned.timestamp = new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
            log.meals[meal].push(cloned);
            copiedCount++;
        });
    });
    if (copiedCount === 0) {
        showToast("The previous day's log was empty.", true);
        return;
    }
    showToast(`Copied ${copiedCount} item${copiedCount === 1 ? '' : 's'} from the previous day.`);
    renderAll();
    saveStateToLocalStorage();
}
// SWIPE BETWEEN DAYS (Today tab only)
let swipeStartX = 0;
let swipeStartY = 0;
let swipeTracking = false;
function initSwipeNavigation() {
    const body = document.body;
    body.addEventListener('touchstart', (e) => {
        swipeTracking = overlayStack.length === 0 && appState.activeTab === 'nutrition' && e.touches.length === 1;
        swipeStartX = e.touches[0].clientX;
        swipeStartY = e.touches[0].clientY;
    }, { passive: true });
    body.addEventListener('touchend', (e) => {
        if (!swipeTracking)
            return;
        swipeTracking = false;
        const diffX = e.changedTouches[0].clientX - swipeStartX;
        const diffY = e.changedTouches[0].clientY - swipeStartY;
        if (Math.abs(diffX) > 90 && Math.abs(diffY) < 50)
            navigateDate(diffX > 0 ? -1 : 1);
    }, { passive: true });
}
